  // ISO 8601 in India Standard Time, e.g. 2026-10-19T23:42:05+05:30
  const t = new Date((d instanceof Date ? d : new Date(d)).getTime() + 330 * 60000);
  return t.toISOString().slice(0, 19) + '+05:30';
